<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
if($action==='delete'){$id=(int)($_POST['id']??0);db()->prepare('DELETE FROM events WHERE id=?')->execute([$id]);audit('event_delete',"Event {$id} deleted");flash('success','Event deleted.');redirect('admin/events.php');}
$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$date=$_POST['event_date']??'';$venue=trim($_POST['venue']??'');$category=trim($_POST['category']??'General');
if($title===''||$desc===''||$date===''||$venue==='')$errors[]='All event fields are required.';
if(!$errors){$q=db()->prepare("INSERT INTO events(title,description,event_date,venue,category,status,created_by) VALUES(?,?,?,?,?,'published',?)");$q->execute([$title,$desc,$date,$venue,$category,current_user()['id']]);audit('event_create',$title);flash('success','Event published.');redirect('admin/events.php');}}
$events=db()->query('SELECT id,title,event_date,venue,category FROM events ORDER BY event_date DESC')->fetchAll();$pageTitle='Manage events';require __DIR__.'/../includes/header.php';?>
<div class="page-title"><span class="eyebrow">ADMINISTRATION</span><h1>Manage events</h1><p>Create and remove campus event listings.</p></div><div class="admin-menu"><a href="<?=e(url('admin/index.php'))?>">← Dashboard</a><a href="<?=e(url('admin/students.php'))?>">Manage students</a></div>
<div class="row g-4"><div class="col-lg-5"><div class="panel"><h2 class="h5 mb-3">Publish an event</h2><?php foreach($errors as $er):?><div class="alert alert-danger"><?=e($er)?></div><?php endforeach;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="mb-3"><label class="form-label" for="title">Event title</label><input class="form-control" id="title" name="title" required></div><div class="mb-3"><label class="form-label" for="description">Description</label><textarea class="form-control" id="description" name="description" rows="3" required></textarea></div><div class="mb-3"><label class="form-label" for="event_date">Date</label><input class="form-control" id="event_date" type="date" name="event_date" required></div><div class="mb-3"><label class="form-label" for="venue">Venue</label><input class="form-control" id="venue" name="venue" required></div><div class="mb-3"><label class="form-label" for="category">Category</label><input class="form-control" id="category" name="category" value="General"></div><button class="btn btn-primary w-100">Publish event</button></form></div></div><div class="col-lg-7"><div class="panel"><h2 class="h5 mb-3">All events</h2><div class="table-responsive"><table class="table"><thead><tr><th>Event</th><th>Date</th><th>Action</th></tr></thead><tbody><?php foreach($events as $ev):?><tr><td><b><?=e($ev['title'])?></b><br><small class="muted"><?=e($ev['venue'])?></small></td><td><?=e(date('d M Y',strtotime($ev['event_date'])))?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$ev['id']?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Delete this event?">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
